; The Gilded Flagon, the Lantern Market's tavern: the bar along the left with the keeper behind it and
; the kegs and the crockery behind them on the flagstones, the hearth in the back wall with the bard in
; front of it on the rug, tables round the room, and the regulars. Dim, the hearth and the candles
; lighting it. The door's in the front wall, back out to wherever you came in.

[map]
id = gilded-flagon
name = The Gilded Flagon
tileset = interior
size = 22 15
dark = yes
ambient = 0.55
fog = no
music = Exploring

[legend]
- = floor-wood
s = floor-stone
r = rug
# = wall-top
| = wall-face
_ = wall-base

